"tableReferences": [{
  "projectId": "bigquery-public-data", "datasetId": "thelook_ecommerce", "tableId": "orders",
  "schema": {
    "description": "Data for orders in The Look, a fictitious ecommerce store.",
    "synonyms": ["sales"],
    "tags": ["sale", "order", "sales_order"],
    "fields": [{"name": "status", "description": "The current status of the order."}]
  }
}],
"example_queries": [{
  "naturalLanguageQuestion": "How many orders are there?",
  "sqlQuery": "SELECT COUNT(*) FROM `bigquery-public-data.thelook_ecommerce.orders`"
}]

view: orders {
  dimension: id { primary_key: yes sql: ${TABLE}.id ;; }
  dimension: amount {
    type: number
    description: "Order amount"
    synonyms: ["sales"]
    sql: ${TABLE}.amount ;;
  }
  measure: total_amount {
    type: sum
    sql: ${amount} ;;
  }
}
